/* --- Checkbox BOM (Animated) --- */
.checkbox-bom input[type=checkbox] {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  width: 24px;
  aspect-ratio: 1;
  border: 2px solid #E4E6E8;
  border-radius: 50%;
  background: #fff;
  cursor: pointer;
  margin: 0;
}
.checkbox-bom input[type=checkbox]:focus {
  outline: 0;
}
.checkbox-bom input[type=checkbox]:checked + label {
  animation: bom-splash 0.6s ease forwards;
}
