  stroke-dashoffset: 0;
}
.checkbox-bom label {
  width: 24px;
  height: 24px;
  background: none;
  border-radius: 50%;
  -webkit-filter: url("#bom-goo");
  filter: url("#bom-goo");
  transform: translate3d(0, 0, 0);
  pointer-events: none;
}
.checkbox-bom .checkbox-bom-checkmark {
  pointer-events: none;
  top: 5px;
  left: 4px;
  stroke: #FFFFFF;
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 19;
  stroke-dashoffset: 19;
  transition: stroke-dashoffset 0.3s ease;
  transition-delay: 0.2s;
}

@keyframes bom-splash {
  40% {
    background: #3761EB;
    box-shadow: 0 -18px 0 -8px #3761EB, 16px -8px 0 -8px #3761EB, 16px 8px 0 -8px #3761EB, 0 18px 0 -8px #3761EB, -16px 8px 0 -8px #3761EB, -16px -8px 0 -8px #3761EB;
  }
  100% {
    background: #3761EB;
    box-shadow: 0 -36px 0 -10px transparent, 32px -16px 0 -10px transparent, 32px 16px 0 -10px transparent, 0 36px 0 -10px transparent, -32px 16px 0 -10px transparent, -32px -16px 0 -10px transparent;
