/* --- Checkbox Magi --- */
.checkbox-magic input[type=checkbox] {
  display: none;
  visibility: hidden;
}
.checkbox-magic input[type=checkbox]:checked + label {
  border-color: transparent;
  background: #3761EB;
  animation: magic-jelly 0.6s ease;
}
.checkbox-magic input[type=checkbox]:checked + label:after {
  opacity: 1;
  transform: rotate(45deg) scale(1);
}
.checkbox-magic label {
  top: 1px;
  width: 17px;
  height: 17px;
  border: 1px solid #E4E6E8;
  border-radius: 3px;
  vertical-align: middle;
  transition: background 0.1s ease;
  cursor: pointer;
}
.checkbox-magic label:after {
  content: "";
  top: 1px;
  left: 5px;
  width: 5px;
  height: 11px;
  opacity: 0;
  transform: rotate(45deg) scale(0);
  border-right: 2px solid #FFFFFF;
  border-bottom: 2px solid #FFFFFF;
  transition: all 0.3s ease;
  transition-delay: 0.15s;
}

@keyframes magic-jelly {
  from {
    transform: scale(1, 1);
  }
  30% {
    transform: scale(1.25, 0.75);
  }
  40% {
    transform: scale(0.75, 1.25);
  }
  50% {
    transform: scale(1.15, 0.85);
  }
  65% {
    transform: scale(0.95, 1.05);
  }
  75% {
    transform: scale(1.05, 0.95);
  }
  to {
    transform: scale(1, 1);
